return {["fb05_01"]={["dsc"]=[[这里是华山脚下，虽然远离县城，却没有什麽山贼草寇在附近出没。西面是一个小村庄，看来村子里人家不多，村民们过着日出而作，日落而息的宁静生活。穿过这个小村子，就是上华山的山路了。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb05_01]],["item1"]=[[bfitem2]],["item2"]=[[bfitem3]],["name"]=[[南村口]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb05_02]],["visible"]=1},["fb05_02"]={["down"]=[[fb05_01]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。一条碎石路，往北通向村子的中心，往南就是出村的路了。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_02]],["item1"]=[[bfitem4]],["item2"]=[[dr3trigger01]],["name"]=[[碎石路]],["permission"]=1,["role1"]=[[fb05r02_1]],["role2"]=[[fb05r02_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_03]],["visible"]=1},["fb05_03"]={["down"]=[[fb05_02]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。这是一条南北向的碎石路，东面是一间小土房。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_03]],["name"]=[[碎石路]],["permission"]=1,["right"]=[[fb05_04]],["role1"]=[[fb05r03_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_06]],["visible"]=1},["fb05_04"]={["BgmDown"]=1,["dsc"]=[[这是一间用土坯搭成的房屋，屋里只有几件残破的家俱。在靠门口的墙角有一只空空的笼子，大概曾经用来养过鸡、鸭之类的家禽。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_04]],["item1"]=[[fb05item32]],["left"]=[[fb05_03]],["name"]=[[小土房]],["permission"]=2,["role1"]=[[fb05r04_1]],["role2"]=[[fb05r04_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_05"]={["BgmDown"]=1,["dsc"]=[[这是一条黑暗、肮脏的小巷，空气中仿佛飘扬着一股罪恶的气息，西北边通向小巷深处，正人君子是不会往那边走去的。往东走就会回到村中大路了。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_05]],["item1"]=[[bfitem1]],["leftUp"]=[[fb05_07]],["name"]=[[小巷]],["permission"]=1,["right"]=[[fb05_06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_06"]={["down"]=[[fb05_03]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。这是一条南北向的碎石路，西边有一条黑黑暗暗的小巷子。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_06]],["left"]=[[fb05_05]],["name"]=[[碎石路]],["permission"]=1,["role1"]=[[fb05r06_1]],["role2"]=[[fb05r06_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_08]],["visible"]=1},["fb05_07"]={["BgmDown"]=1,["dsc"]=[[这里是小巷的尽头，一只破木箱上摆着几样粗制的赌具，地上乱扔着些鸡骨头，空气中有一股鸡香、酒香和汗臭混杂在一起的味道。看来这里是村内地痞、流氓聚集的地方。]],["enterable"]=1,["id"]=[[fb05_07]],["item1"]=[[fb05item16]],["name"]=[[小巷尽头]],["permission"]=1,["rightDown"]=[[fb05_05]],["role1"]=[[fb05r07_1]],["role2"]=[[fb05r07_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_08"]={["down"]=[[fb05_06]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。这是一条南北向的碎石路，往北就是村子中心的打谷场了，东面是村里唯一的青砖瓦房。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_08]],["name"]=[[碎石路]],["permission"]=1,["right"]=[[fb05_09]],["role1"]=[[ever08_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_14]],["visible"]=1},["fb05_09"]={["BgmDown"]=1,["dsc"]=[[这是一间很普通的青砖瓦房，但在这个小村子里已是首屈一指的“豪宅”了。这里是前厅，厅里的摆设很简单，乡下土财主都很财迷，就算有几个钱儿，也是舍不得花。东边是个小门通向内室。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_09]],["item1"]=[[fb05item18]],["left"]=[[fb05_08]],["name"]=[[前厅]],["permission"]=1,["right"]=[[fb05_10]],["role1"]=[[fb05r09_1]],["role2"]=[[fb05r09_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_10"]={["BgmDown"]=1,["dsc"]=[[这里是一间寝室，屋子中间有一张大床，床上的被褥居然是绸缎的，看来这个土财主对自己并不是十分刻薄。屋里摆着几只木箱子，墙角里有一只大柜子。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_10]],["item1"]=[[fb05item30]],["left"]=[[fb05_09]],["name"]=[[内室]],["permission"]=1,["role1"]=[[fb05r10_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_11"]={["BgmDown"]=1,["dsc"]=[[这是一间甚是简陋的铁匠铺，入门正中是个大铁砧，满地煤渣碎铁，墙上挂着几张犁头，屋子的角落里堆着几把破锄头、镰刀，靠墙放着几把新出炉的铁锤。东面有一个小门，门上挂着个破布帘。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_11]],["item1"]=[[duanzaoronglu1]],["name"]=[[铁匠铺]],["permission"]=2,["role1"]=[[fb05r11_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_15]],["visible"]=1},["fb05_12"]={["BgmDown"]=1,["dsc"]=[[这是一个简单的草棚，地上摆着一堆堆的货物，上山的游客可以在这买些上山用品。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_12]],["name"]=[[草棚]],["permission"]=2,["role1"]=[[fb05r12_1]],["role2"]=[[fb05r12_2]],["role3"]=[[fb05r12_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_17]],["visible"]=1},["fb05_13"]={["BgmDown"]=1,["dsc"]=[[这是一个小房间，屋子里飘着一股大葱加香粉的味道。靠墙摆着张大床，床头有个小梳妆台。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_13]],["name"]=[[民房]],["permission"]=2,["rightUp"]=[[fb05_19]],["role1"]=[[fb05r13_1]],["role2"]=[[fb05r13_2]],["role3"]=[[20xiayuannpc1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_14"]={["down"]=[[fb05_08]],["dsc"]=[[这里是村子的中心，一个平坦的广场，每年秋收打谷就在这。广场东角有棵大槐树，平日茶余饭後，村里的男女老少都爱聚在这里谈天说地。角上有几个大谷堆。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_14]],["item1"]=[[fb05item34]],["item2"]=[[fb05item34]],["item3"]=[[fb05item34]],["item4"]=[[cfitem1]],["leftUp"]=[[fb05_19]],["name"]=[[打谷场]],["permission"]=1,["right"]=[[fb05_15]],["role1"]=[[fb05r14_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_15"]={["down"]=[[fb05_11]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。这是一条东西向的碎石路，往西就是村子中心的打谷场了，南面是一间铁匠铺子，北面是家杂货店。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_15]],["item1"]=[[bfitem5]],["item2"]=[[cfitem2]],["left"]=[[fb05_14]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb05_16]],["role1"]=[[fb05r15_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_20]],["visible"]=1},["fb05_16"]={["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。这是一条东西向的碎石路，北面是间结实的民宅。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_16]],["item1"]=[[cfitem3]],["left"]=[[fb05_15]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb05_17]],["role1"]=[[bfr01_1]],["role2"]=[[fb05r16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_21]],["visible"]=1},["fb05_17"]={["down"]=[[fb05_12]],["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。一条碎石路，往西通向村子的中心，往东就是出村的路了。南面是一间很简陋的草棚。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_17]],["item1"]=[[dr3trigger05]],["left"]=[[fb05_16]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb05_18]],["role1"]=[[fb05r17_1]],["role2"]=[[fb05r17_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_48]],["visible"]=1},["fb05_18"]={["dsc"]=[[这里是华山脚下，虽然远离县城，却没有什麽山贼草寇在附近出没。往东就是上山的路了。西边是一个小村庄，村子里人家并不多，村民们过着日出而作，日落而息的宁静生活。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_18]],["item1"]=[[fb05item15]],["left"]=[[fb05_17]],["name"]=[[东村口]],["permission"]=2,["role1"]=[[fb05r18_1]],["role2"]=[[fb05r18_2]],["role3"]=[[fb05r18_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_19"]={["dsc"]=[[这是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。东南边就是村子中心的打谷场了，西南是间民房。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_19]],["item1"]=[[sy1chufa02]],["item2"]=[[sy11chufa03]],["item3"]=[[sy13chufa03]],["leftDown"]=[[fb05_13]],["leftUp"]=[[fb05_23]],["name"]=[[碎石路]],["permission"]=1,["rightDown"]=[[fb05_14]],["rightUp"]=[[fb05_28]],["role1"]=[[fb05r19_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_20"]={["BgmDown"]=1,["down"]=[[fb05_15]],["dsc"]=[[这是一间小小的杂货店，经营些油、盐、酱、醋及日用百货，村子里的人多数是很穷，除了生活必需品，这里很少贩卖其它物品。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_20]],["name"]=[[杂货店]],["permission"]=2,["role1"]=[[fb05r20_1]],["role2"]=[[fb05r20_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_21"]={["BgmDown"]=1,["down"]=[[fb05_16]],["dsc"]=[[这是一间十分简陋，四壁漏风的小房子，屋子里连一张像样的床都没有，只有一面门板上面铺着些干草。这屋子的主人一定是贫困潦倒，穷的叮当响。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_21]],["item1"]=[[dr3wp01a]],["name"]=[[民宅]],["permission"]=2,["role1"]=[[fb05r21_1]],["role2"]=[[20xiayuannpc4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_22"]={["dsc"]=[[这里是华山脚下，虽然远离县城，却没有什麽山贼草寇在附近出没。东面是一个小村庄，看来村子里人家不多，村民们过着日出而作，日落而息的宁静生活。穿过这个小村子，就是上华山的山路了。北边有间破房子。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_22]],["item1"]=[[cg2item1]],["item2"]=[[dr3trigger04]],["name"]=[[西村口]],["permission"]=1,["right"]=[[fb05_23]],["role1"]=[[fb05r22_1a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_24]],["visible"]=1},["fb05_23"]={["dsc"]=[[是一个宁静的小村子，稀稀落落的分布着几十间土坯泥房，看来村中人家不多，而且大都生活很艰辛。东北边有间小庙，庙匾上的字早已模糊不清，看不出是什麽庙了。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb05_23]],["item1"]=[[xinshoudanglu1]],["left"]=[[fb05_22]],["name"]=[[碎石路]],["permission"]=1,["rightDown"]=[[fb05_19]],["rightUp"]=[[fb05_25]],["role1"]=[[fb05r23_1]],["role2"]=[[fb05r23_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_24"]={["BgmDown"]=1,["down"]=[[fb05_22]],["dsc"]=[[这是一间很结实的房子，虽然也是间土坯房，但看的出建造的比村里其他的土坯房要好很多。墙上挂着、地下摆着一些农具。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb05_24]],["item1"]=[[dr3wp02a]],["name"]=[[民宅]],["permission"]=2,["role1"]=[[fb05r24_1]],["role2"]=[[fb05r24_2]],["role3"]=[[20xiayuannpc2]],["role4"]=[[20xiayuannpc3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_25"]={["dsc"]=[[这是一间十分破旧的小庙，庙里供的神像是赵玄坛，神像已经很残破了，神案上也积了很多尘土，看来已有很久没人来上香进供了。大概村民贫困的太久，已不再寄望於财神爷降福给他们了。]],["enterable"]=1,["id"]=[[fb05_25]],["item1"]=[[fb05item1]],["item2"]=[[fb05item35]],["item3"]=[[fb05item35]],["leftDown"]=[[fb05_23]],["name"]=[[玄坛庙]],["permission"]=2,["role1"]=[[fb05r25_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_26"]={["dsc"]=[[这里是密道，黑乎乎的，什么也看不真切，你只能摸索着向前走，很费劲的钻过一个个的密道。]],["enterable"]=1,["id"]=[[fb05_26]],["left"]=[[fb05_25]],["name"]=[[密道]],["permission"]=2,["right"]=[[fb05_27]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_27"]={["dsc"]=[[这里是密道的尽头了，黑乎乎的，前方已经没有路了。]],["enterable"]=1,["id"]=[[fb05_27]],["item1"]=[[fb05item2]],["item2"]=[[fb05item3]],["left"]=[[fb05_26]],["name"]=[[密道尽头]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_28"]={["dsc"]=[[碎石路的尽头是一道悬崖。陡峭的崖壁好似刀削斧劈一般笔直，崖尖直上云霄。山崖脚下还有一片碧绿的小湖，一时间湖光山色映入眼帘，美不胜收。]],["enterable"]=1,["id"]=[[fb05_28]],["item1"]=[[fb05item11]],["item2"]=[[ycitem1]],["leftDown"]=[[fb05_19]],["name"]=[[悬崖边]],["permission"]=2,["role1"]=[[fb05r28_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_29"]={["dsc"]=[[这个是个大湖，湖水一平入镜，月光映入湖中，湖心也是一轮皎洁的圆月。湖畔还生着一丛丛的各式各样的茶花。在月光下摇曳生姿。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb05_29]],["item1"]=[[fb05item20]],["item2"]=[[fb05item33]],["item3"]=[[ycitem3]],["name"]=[[湖边]],["permission"]=2,["right"]=[[fb05_30]],["stepMusic"]=[[youyong]],["up"]=[[fb05_31]],["visible"]=1},["fb05_30"]={["dsc"]=[[但听得耳边轰隆隆的响声越来越大，山崖也逐渐变得倾斜，而不再像上面那么陡峭笔立了，终于到达谷底了。只见上面的上崖一条大瀑布如玉龙悬空，滚滚而下，倾入了一座清澈异常的大湖之中。甚为壮观。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb05_30]],["item1"]=[[fb05item36]],["item2"]=[[fb05item37]],["left"]=[[fb05_29]],["name"]=[[谷底]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_31"]={["down"]=[[fb05_29]],["dsc"]=[[这里四周没有丝毫的光亮，每前进一步，都要先试探个虚实，但是却觉得脚下平整，便似走在石板路上一般，只见道路不断地往下倾斜，越走越低。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb05_31]],["name"]=[[岩洞]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb05_32]],["visible"]=1},["fb05_32"]={["down"]=[[fb05_31]],["dsc"]=[[穿过岩洞，突然之间，手碰到一个冷冰冰的圆物，原来是个门环，门环的后面象是一扇铜铁铸成的大门，十分沉重。即使是臂力很好的人，推它也觉得甚为吃力。]],["enterable"]=1,["id"]=[[fb05_32]],["name"]=[[石室大门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb05_33]],["visible"]=1},["fb05_33"]={["down"]=[[fb05_32]],["dsc"]=[[这是一个比较大的圆形石洞，光亮从左边的窗口透了过来，细看那窗的时候，发现原来是镶在石壁上的一块大水晶透过水晶向外看去，只见鱼虾水族来回游动，原来你竟处身水底之中。]],["enterable"]=1,["id"]=[[fb05_33]],["left"]=[[fb05_35]],["name"]=[[石洞]],["permission"]=2,["right"]=[[fb05_38]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_34]],["visible"]=1},["fb05_34"]={["down"]=[[fb05_33]],["dsc"]=[[这里是一个极大的石室，比之外面的任何一个都大了数倍，室中一排排地列满了木制成的书架，可是书架上却空荡荡地连一本书也没有，走近看时，只见书架上贴满了“昆仑派”，“少林派”，“青城派”之类的条目，想象当年所列，皆是各门各派的武功秘籍。]],["enterable"]=1,["id"]=[[fb05_34]],["item1"]=[[fb05item23]],["item2"]=[[fb05item26]],["item3"]=[[fb05item40]],["item4"]=[[fb05item39]],["name"]=[[石室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_35"]={["dsc"]=[[这是一段长长的石级，四周由于缺乏光亮，难免有点阴深深的感觉，石级向着东西两面伸展，一眼望去，不可以望到尽头。]],["enterable"]=1,["id"]=[[fb05_35]],["left"]=[[fb05_36]],["name"]=[[石级]],["permission"]=2,["right"]=[[fb05_33]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_37]],["visible"]=1},["fb05_36"]={["dsc"]=[[这是一个石头砌成的房间，因为好久没有人来过，散发着一些很难闻的气味，房间中到处可以看到蛛丝和虫迹。]],["enterable"]=1,["id"]=[[fb05_36]],["item1"]=[[fb05item23]],["item2"]=[[ycitem2]],["item3"]=[[fb05item40]],["item4"]=[[fb05item39]],["name"]=[[石室]],["permission"]=2,["right"]=[[fb05_35]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_37"]={["down"]=[[fb05_35]],["dsc"]=[[这是一间布置成卧室模样的小房间，有张石床，床上摆着个小小的木头制成的摇篮，墙壁上悬着一个七弦琴，弦线都已经断了。]],["enterable"]=1,["id"]=[[fb05_37]],["item1"]=[[fb05item24]],["item2"]=[[fb05item23]],["item3"]=[[fb05item40]],["item4"]=[[fb05item39]],["name"]=[[房间]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_38"]={["dsc"]=[[这是一段长长的石级，四周由于缺乏光亮，难免有点阴深深的感觉，石级向着东西两面伸展，一眼望去，不可以望到尽头。]],["enterable"]=1,["id"]=[[fb05_38]],["left"]=[[fb05_33]],["name"]=[[石级]],["permission"]=2,["right"]=[[fb05_40]],["stepMusic"]=[[jiaobu]],["up"]=[[fb05_39]],["visible"]=1},["fb05_39"]={["down"]=[[fb05_38]],["dsc"]=[[可以看出这里以前曾经是一个下棋的地方，房间除了一张石几，两只软椅之外，空荡荡的一无所有，石几上刻着纵横十九道棋路，棋局上布着二百多颗棋子，却是黑白对峙，竟然是一局没有下完的棋。]],["enterable"]=1,["id"]=[[fb05_39]],["item1"]=[[fb05item25]],["name"]=[[房间]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_40"]={["dsc"]=[[这是一个石头砌成的房间，因为好久没有人来过，散发着一些很难闻的气味，房间中到处可以看到蛛丝和虫迹。]],["enterable"]=1,["id"]=[[fb05_40]],["item1"]=[[fb05item23]],["item2"]=[[fb05item40]],["item3"]=[[fb05item39]],["left"]=[[fb05_38]],["name"]=[[石室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb05_41]],["visible"]=1},["fb05_41"]={["down"]=[[fb05_40]],["dsc"]=[[这是一段向南北方向伸展的石级，四周由于缺乏光亮，难免有点阴深深的感觉，北面是个月形的铜门，南面是个石室。]],["enterable"]=1,["id"]=[[fb05_41]],["name"]=[[石级]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb05_42]],["visible"]=1},["fb05_42"]={["down"]=[[fb05_41]],["dsc"]=[[这是一个月形的铜门，门旁的壁上凿着“琅环福地”四个大字。]],["enterable"]=1,["id"]=[[fb05_42]],["item1"]=[[fb05item21]],["left"]=[[fb05_43]],["name"]=[[铜门]],["permission"]=2,["role1"]=[[fb05r42_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_43"]={["dsc"]=[[你只觉得眼前陡然一亮，一个宫装的美女，正拿着一把长剑，对准了你的胸膛！……一场虚惊之后，你才发现原来只是个白玉雕成的玉像，但是看上去却与真人一般无异。玉像的一双眸子莹然有光，神采飞扬。你此时只觉得神驰目眩，竟如着魔中邪，眼光再也离不开玉像……]],["enterable"]=1,["id"]=[[fb05_43]],["item1"]=[[fb05item9]],["item2"]=[[fb05item10]],["name"]=[[房间]],["permission"]=2,["right"]=[[fb05_42]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb05_44"]={["dsc"]=[[这里是一个石室，旁边有一些石桌石椅，似乎之前有人居住过。]],["enterab